1	// Package command implements a reusable command tree with arbitrary-depth
2	// subcommands and aliases.
3	//
4	// Nodes are created with New and attached to their parent with (*Node).Add.
5	// Execution starts at any node through (*Node).Execute, which descends one
6	// argument at a time, matching only exact, case-sensitive primary names and
7	// aliases; aliases resolve to the canonical primary name reported to the
8	// handler. Plain-text help is generated on demand through
9	// (*Node).WriteHelp; neither Execute nor WriteHelp interprets "--help" or
10	// "-h". Apart from the WriteHelp output itself the package never produces
11	// help text, completions, or log output, and it never writes to the
12	// stdout/stderr writers passed to Execute — only node handlers do.
13	package command
14	
15	import (
16		"context"
17		"errors"
18		"fmt"
19		"io"
20		"strings"
21	)
22	
23	// Sentinel errors describing registration and execution failures.
24	//
25	// Callers must use errors.Is rather than direct comparison where the
26	// documentation promises a wrapping error type (ErrInvalidName and
27	// ErrUnknownCommand); the others are returned directly.
28	var (
29		// ErrInvalidName indicates an empty or otherwise illegal primary name
30		// or alias. It is wrapped by *NameError carrying the offending name.
31		ErrInvalidName = errors.New("command: invalid command name")
32	
33		// ErrInvalidCommand is returned when Add receives a nil node (or a node
34		// that cannot legally be attached, such as an ancestor of the parent).
35		ErrInvalidCommand = errors.New("command: invalid command node")
36	
37		// ErrNameConflict indicates a duplicated primary name or alias under
38		// the same parent, including aliases duplicated inside one node. It is
39		// wrapped by *ConflictError carrying the duplicated name.
40		ErrNameConflict = errors.New("command: command name conflict")
41	
42		// ErrAlreadyAttached indicates that Add was called for a node that
43		// already has a parent. It is wrapped by *AttachedError.
44		ErrAlreadyAttached = errors.New("command: command already attached to a parent")
45	
46		// ErrUnknownCommand marks a LookupError produced when an argument
47		// matches neither a child's primary name nor one of its aliases.
48		ErrUnknownCommand = errors.New("command: unknown command")
49	
50		// ErrCommandRequired is returned when arguments run out at a node that
51		// has no handler, so no action can run.
52		ErrCommandRequired = errors.New("command: command required but no argument remained")
53	)
54	
55	// NameError wraps ErrInvalidName and reports the offending primary name or
56	// alias.
57	type NameError struct {
58		// Name is the primary name or alias that failed validation.
59		Name string
60	}
61	
62	func (e *NameError) Error() string {
63		return fmt.Sprintf("command: invalid command name %q", e.Name)
64	}
65	
66	// Unwrap exposes ErrInvalidName for errors.Is and errors.As.
67	func (e *NameError) Unwrap() error { return ErrInvalidName }
68	
69	// ConflictError wraps ErrNameConflict and reports the name that collided
70	// with an already registered primary name or alias.
71	type ConflictError struct {
72		// Name is the primary name or alias that collided.
73		Name string
74	}
75	
76	func (e *ConflictError) Error() string {
77		return fmt.Sprintf("command: command name %q is already registered", e.Name)
78	}
79	
80	// Unwrap exposes ErrNameConflict for errors.Is and errors.As.
81	func (e *ConflictError) Unwrap() error { return ErrNameConflict }
82	
83	// AttachedError wraps ErrAlreadyAttached and reports the node that was
