        set -a seen $parts[1]
        if test "$parts[2]" = v
            if test $j -eq $len
                set want_value 1
            end
            return
        end
        set j (math $j + 1)
    end
end

function __ID___offer_long
    for spec in (__ID___options $argv[1])
        set -l parts (string split '|' -- $spec)
        if test "$parts[4]" != 1
            if contains -- $parts[1] $seen
