cat > /tmp/compgen/edge.go <<'EOF'
package main

import (
	"fmt"
	"os"

	"github.com/f5dt1artum/shellsmith/command"
)

func main() {
	// 1. bare root, no children, no parser
	bare := command.New("bare", "", nil, nil)
	// 2. leaf root with parser
	leaf := command.New("leaf", "", nil, nil)
	lp, _ := command.NewParser([]command.Option{
		{Long: "all", Short: "a", Type: command.TypeBool},
		{Long: "out", Short: "o"},
	}, nil)
	// 3. root with children, no parsers at all
	tree := command.New("tree", "", nil, nil)
	_ = tree.Add(command.New("one", "first", []string{"1"}, nil))
	// 4. description with nasty chars
	nasty := command.New("nasty", "", nil, nil)
	_ = nasty.Add(command.New("run", "it's \"quoted\"\nnewline $var `tick` \\slash [br] {br} ;&|<>", []string{"r"}, nil))

	for _, shell := range []string{"bash", "zsh", "fish", "powershell"} {
		for name, gen := range map[string]func() error{
			"bare":  func() error { return bare.WriteCompletion(shell, nil, os.Stdout) },
			"leaf":  func() error { return leaf.WriteCompletion(shell, map[*command.Node]*command.Parser{leaf: lp}, os.Stdout) },
			"tree":  func() error { return tree.WriteCompletion(shell, nil, os.Stdout) },
			"nasty": func() error { return nasty.WriteCompletion(shell, nil, os.Stdout) },
		} {
			f, _ := os.Create(fmt.Sprintf("/tmp/compgen/edge-%s-%s.%s", name, shell, shell))
			_ = gen()
			_ = f.Close()
		}
	}
	// regenerate properly into files
	for _, shell := range []string{"bash", "zsh", "fish", "powershell"} {
		for name, root := range map[string]*command.Node{"bare": bare, "leaf": leaf, "tree": tree, "nasty": nasty} {
			var pm map[*command.Node]*command.Parser
			if name == "leaf" {
				pm = map[*command.Node]*command.Parser{leaf: lp}
			}
			f, _ := os.Create(fmt.Sprintf("/tmp/compgen/edge-%s.%s", name, shell))
			if err := root.WriteCompletion(shell, pm, f); err != nil {
				panic(err)
			}
			_ = f.Close()
		}
	}
	fmt.Println("done")
}
EOF
